create sequence if not exists maintenance_work_order_seq;
create table maintenance_assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),asset_code text not null,name text not null,location text,criticality text not null default'medium'check(criticality in('low','medium','high','critical')),status text not null default'operational'check(status in('operational','down','maintenance','standby','retired')),active boolean not null default true,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,asset_code));
create table maintenance_work_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_order_number text not null unique,asset_id uuid not null references maintenance_assets(id),status text not null default'open'check(status in('open','in_progress','waiting_parts','waiting_external','completed','cancelled')),priority text not null default'medium'check(priority in('low','medium','high','critical')),title text not null,problem_description text,root_cause text,resolution text,requested_by uuid,requested_by_email text,requested_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,updated_at timestamptz not null default now());
create table maintenance_downtime_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),asset_id uuid not null references maintenance_assets(id),work_order_id uuid references maintenance_work_orders(id),started_at timestamptz not null default now(),ended_at timestamptz,reason text,started_by uuid,ended_by uuid);create unique index maintenance_one_active_down on maintenance_downtime_events(asset_id)where ended_at is null;
create table maintenance_work_order_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_order_id uuid not null references maintenance_work_orders(id),from_status text,to_status text not null,changed_by uuid,changed_by_email text,changed_at timestamptz not null default now());
alter table maintenance_assets enable row level security;alter table maintenance_work_orders enable row level security;alter table maintenance_downtime_events enable row level security;alter table maintenance_work_order_history enable row level security;revoke all on maintenance_assets,maintenance_work_orders,maintenance_downtime_events,maintenance_work_order_history from anon,authenticated;grant all on maintenance_assets,maintenance_work_orders,maintenance_downtime_events,maintenance_work_order_history to service_role;grant usage,select on sequence maintenance_work_order_seq to service_role;
create or replace function maintenance_report_problem(p_organization_id uuid,p_asset_id uuid,p_title text,p_description text,p_priority text,p_machine_stopped boolean,p_actor_id uuid,p_actor_email text)returns uuid language plpgsql security definer set search_path=public as $$declare w uuid;n text;begin if not exists(select 1 from maintenance_assets where id=p_asset_id and organization_id=p_organization_id and active)then raise exception'Invalid asset';end if;n='WO-'||extract(year from now()at time zone'Australia/Brisbane')::int||'-'||lpad(nextval('maintenance_work_order_seq')::text,6,'0');insert into maintenance_work_orders(organization_id,work_order_number,asset_id,priority,title,problem_description,requested_by,requested_by_email)values(p_organization_id,n,p_asset_id,p_priority,p_title,p_description,p_actor_id,p_actor_email)returning id into w;insert into maintenance_work_order_history values(gen_random_uuid(),p_organization_id,w,null,'open',p_actor_id,p_actor_email,now());if p_machine_stopped then insert into maintenance_downtime_events(organization_id,asset_id,work_order_id,reason,started_by)values(p_organization_id,p_asset_id,w,p_title,p_actor_id);update maintenance_assets set status='down',updated_at=now()where id=p_asset_id;end if;return w;end$$;
create or replace function maintenance_transition_work_order(p_organization_id uuid,p_work_order_id uuid,p_status text,p_root_cause text,p_resolution text,p_actor_id uuid,p_actor_email text)returns void language plpgsql security definer set search_path=public as $$declare old text;a uuid;begin select status,asset_id into old,a from maintenance_work_orders where id=p_work_order_id and organization_id=p_organization_id for update;if old is null then raise exception'Work order not found';end if;if p_status='completed'and nullif(trim(p_resolution),'')is null then raise exception'Resolution required';end if;update maintenance_work_orders set status=p_status,root_cause=coalesce(nullif(trim(p_root_cause),''),root_cause),resolution=coalesce(nullif(trim(p_resolution),''),resolution),started_at=case when p_status='in_progress'then coalesce(started_at,now())else started_at end,completed_at=case when p_status='completed'then now()else completed_at end,updated_at=now()where id=p_work_order_id;insert into maintenance_work_order_history values(gen_random_uuid(),p_organization_id,p_work_order_id,old,p_status,p_actor_id,p_actor_email,now());if p_status='completed'then update maintenance_downtime_events set ended_at=now(),ended_by=p_actor_id where work_order_id=p_work_order_id and ended_at is null;update maintenance_assets set status='operational',updated_at=now()where id=a and not exists(select 1 from maintenance_downtime_events where asset_id=a and ended_at is null);elsif p_status='in_progress'then update maintenance_assets set status='maintenance',updated_at=now()where id=a and status<>'down';end if;end$$;
revoke all on function maintenance_report_problem(uuid,uuid,text,text,text,boolean,uuid,text),maintenance_transition_work_order(uuid,uuid,text,text,text,uuid,text)from public,anon,authenticated;grant execute on function maintenance_report_problem(uuid,uuid,text,text,text,boolean,uuid,text),maintenance_transition_work_order(uuid,uuid,text,text,text,uuid,text)to service_role;
